import {makeChoice} from './simple-choice.js';
import {bindAmountInput,parseAmount} from './amount-input.js';
import {moneyParts} from './money.js';
import {financeTotals,financeSummary} from './finance-math.js';
import {settlementTotals} from './commission-exchange.js';
import {offerParts} from './offers.js';
import {installHelp} from './admin-help.js';
export function initAdminOperations({form,node,getItems,openVehicle,notify}){
 const choices=[];
 for(const [name,list,editable]of [['condition',['Nuevo','Seminuevo','Usado'],false],['city',['Santa Cruz de la Sierra','La Paz','El Alto','Cochabamba','Sucre','Tarija','Oruro','Potosí','Trinidad','Cobija','Montero','Sacaba','Quillacollo','Riberalta'],true],['currency',null,false],['status',null,false]])choices.push(makeChoice(form.elements[name],list,{node,label:form.elements[name].closest('label').firstChild.textContent.trim(),editable}));
 const country=form.elements.country;country.value='Bolivia';country.readOnly=true;country.removeAttribute('list');form.elements.color.removeAttribute('list');form.elements.color.placeholder='Escribe el color de esta unidad';const price=bindAmountInput(form.elements.price);
 const offerLabel=node('label','offer-control'),offer=node('input');offer.type='checkbox';offer.name='offerEnabled';offerLabel.append(offer,node('span','','Mostrar como oferta: antes / ahora'));form.elements.currency.closest('label').after(offerLabel);const offerNote=node('small','offer-explanation');offerLabel.after(offerNote);let original=null;
 const theme=node('button','admin-theme-toggle');theme.type='button';theme.id='admin-theme';const header=document.querySelector('.admin-header>div');header.prepend(theme);new ResizeObserver(()=>document.body.style.setProperty('--admin-header-height',Math.ceil(document.querySelector('.admin-header').getBoundingClientRect().height)+'px')).observe(document.querySelector('.admin-header'));let pref;try{pref=localStorage.getItem('torres-admin-theme');}catch{}
 const setTheme=light=>{document.body.classList.toggle('admin-light',light);document.documentElement.style.colorScheme=light?'light':'dark';theme.textContent=light?'☾ Modo oscuro':'☼ Modo claro';theme.setAttribute('aria-label',light?'Activar modo oscuro del administrador':'Activar modo claro del administrador');theme.setAttribute('aria-pressed',String(light));};setTheme(pref==='light');theme.onclick=()=>{const light=!document.body.classList.contains('admin-light');setTheme(light);try{localStorage.setItem('torres-admin-theme',light?'light':'dark');}catch{}};
 const nav=node('nav','admin-module-nav');nav.setAttribute('aria-label','Módulos de administración');nav.hidden=true;header.before(nav);const sales=node('section');sales.id='sales';sales.hidden=true;document.querySelector('#dashboard').after(sales);
 function showModule(id){for(const key of ['auth','dashboard','editor','sales'])document.querySelector('#'+key).hidden=key!==id;for(const b of nav.children)b.setAttribute('aria-current',b.dataset.module===id?'page':'false');window.scrollTo({top:0,behavior:'instant'});}
 for(const [id,title]of [['dashboard','Vehículos'],['sales','Ventas y comisiones']]){const b=node('button','',title);b.type='button';b.dataset.module=id;b.onclick=()=>showModule(id);nav.append(b);}
 let privateCurrencyTouched=false;
 const section=node('section','private-finance');section.innerHTML='<div class="private-heading"><span class="eyebrow">SOLO PARA ADMINISTRACIÓN</span><h2>Acuerdo privado y cierre de venta</h2><p>Define el acuerdo, registra la venta real y luego el cobro de tu comisión. Estos datos son privados.</p></div><div class="finance-groups"></div><div class="finance-approval" hidden></div><div class="finance-preview" aria-live="polite"></div><p class="finance-note">Solo suma a ventas al guardar el vehículo como Vendido. Los tipos de cambio quedan guardados con tu cierre.</p>';
 document.querySelector('#save').before(section);const groups=section.querySelector('.finance-groups'),fields={},formats=new Map();let grid;
 const group=(title,description)=>{const block=node('fieldset','finance-group');block.append(node('legend','',title),node('p','',description));grid=node('div','finance-fields');block.append(grid);groups.append(block);};
 const add=(key,label,type='text',options)=>{const wrapper=node('label','',label),input=node(type==='select'?'select':type==='textarea'?'textarea':'input');input.id='finance-'+key;if(input.tagName==='INPUT')input.type=type==='amount'?'text':type;input.setAttribute('aria-label',label);if(options)for(const [value,title]of options){const o=node('option','',title);o.value=value;input.append(o);}wrapper.append(input);grid.append(wrapper);fields[key]=input;if(type==='amount')formats.set(key,bindAmountInput(input,draw));if(type==='select')choices.push(makeChoice(input,null,{node,label}));return wrapper;};
 const currencies=[['BOB','Bs · Bolivianos'],['USD','US$ · Dólares']];
 group('Acuerdo con el propietario','Condiciones previas y límite de negociación.');add('ownerName','Propietario / cliente (privado)');add('currency','Moneda de la venta privada','select',currencies);add('minSalePrice','Precio mínimo de venta autorizado','amount');add('mode','Cómo se calcula tu comisión','select',[['percent','Porcentaje del precio final'],['fixed','Comisión fija pactada'],['margin','Excedente sobre el monto del propietario']]);const rate=add('rate','Comisión pactada (%)','number');fields.rate.min=0;fields.rate.max=100;fields.rate.step='.01';const fixed=add('fixedCommission','Comisión fija pactada','amount'),target=add('ownerTarget','Monto que debe recibir el propietario','amount');
 group('Venta negociada','Todos estos importes usan la moneda de la venta privada.');add('salePrice','Precio final negociado de venta','amount');add('saleDate','Fecha de cierre','date');add('costs','Gastos a cargo de tu comisión','amount');
 group('Cobro y tipo de cambio','Puedes cobrar en otra moneda. Registra Bs por US$ 1; no se supone una cotización fija.');add('payoutCurrency','Moneda de cobro de tu comisión','select',currencies);const agreed=add('exchangeRate','Cambio acordado · Bs por US$ 1','amount'),actual=add('receivedRate','Cambio aplicado al cobrar · Bs por US$ 1','amount');add('received','Comisión que ya cobraste','amount');add('notes','Notas del acuerdo (privadas)','textarea');
 const approval=section.querySelector('.finance-approval'),approvalLabel=node('label','','Autorización adicional del propietario para vender bajo el mínimo');fields.belowMinimumApproval=node('textarea');fields.belowMinimumApproval.id='finance-belowMinimumApproval';approvalLabel.append(fields.belowMinimumApproval);approval.append(approvalLabel);
 function capture(){return Object.fromEntries(Object.entries(fields).map(([key,input])=>[key,formats.has(key)?parseAmount(input.value):input.value]));}
 const cash=(n,c)=>`${c==='BOB'?'Bs':'US$'} ${Number(n||0).toLocaleString('en-US',{maximumFractionDigits:2})}`;
 function cards(title,entries,primary=false){const block=node('section','finance-result-block'+(primary?' primary':''));block.append(node('h3','',title));const row=node('div','finance-result-grid');for(const [label,value,currency]of entries){const card=node('div');card.append(node('small','',label),node('strong',value<0?'loss':'',cash(value,currency)));row.append(card);}block.append(row);return block;}
 function draw(){if(!fields.mode)return;const f=capture(),t=financeTotals(f),p=settlementTotals(f,t),currency=f.currency;rate.hidden=f.mode!=='percent';fixed.hidden=f.mode!=='fixed';target.hidden=f.mode!=='margin';agreed.hidden=actual.hidden=!p.foreign;approval.hidden=!(f.salePrice>0&&f.minSalePrice!==null&&f.salePrice<f.minSalePrice);const preview=section.querySelector('.finance-preview');preview.replaceChildren();const publicMoney={amount:parseAmount(form.elements.price.value),currency:form.elements.currency.value},old=moneyParts(original||{}),existing=offerParts(original||{});offerNote.textContent=offer.checked?`Antes: ${old.currency===publicMoney.currency&&old.amount>publicMoney.amount?cash(old.amount,old.currency):existing?cash(existing.before,existing.currency):'baja un precio previamente guardado'} · Ahora: ${cash(publicMoney.amount,publicMoney.currency)}`:'Actívalo después de bajar el precio de una unidad ya guardada.';
 if(f.minSalePrice!==null&&publicMoney.currency===currency&&publicMoney.amount)preview.append(node('p','negotiation-room',`Margen autorizado: ${cash(publicMoney.amount-f.minSalePrice,currency)} · Mínimo privado: ${cash(f.minSalePrice,currency)}.`));
 if(!t.recorded){preview.append(node('p','','Completa el precio final para simular tu cierre.'));return;}
 if((f.mode==='percent'&&parseAmount(f.rate)===null)||(f.mode==='fixed'&&f.fixedCommission===null)||(f.mode==='margin'&&f.ownerTarget===null)){preview.append(node('p','finance-warning','Completa el acuerdo de comisión.'));return;}
 preview.append(node('strong','',form.elements.status.value==='sold'?'Cierre registrado al guardar':'Simulación · todavía no suma a ventas'));
 preview.append(cards('Distribución de la venta',[['Venta real',t.sale,currency],['Para el propietario',t.ownerPayout,currency],['Tu comisión bruta',t.gross,currency]]));preview.append(cards('Tu resultado',[['Gastos',t.costs,currency],['Ganancia neta devengada',t.net,currency]],true));
 if(!p.valid)preview.append(node('p','finance-warning','Completa los tipos de cambio para convertir la comisión.'));
 else{preview.append(cards('Cobro de comisión',[['Comisión al cambio acordado',p.expected,p.currency],['Efectivamente cobrado',p.received,p.currency],['Pendiente equivalente',p.pendingBase,currency]]));if(p.foreign){preview.append(node('p','finance-note',`Cobrado equivalente: ${cash(p.receivedBase,currency)} al cambio aplicado. Pendiente en moneda de cobro: ${cash(p.pending,p.currency)} al cambio acordado. Los gastos se registran en ${currency}.`),cards('Efecto del cambio en lo cobrado',[['Diferencia frente al cambio acordado',p.fxDifference,'BOB']]));}}
 if(t.belowMinimum)preview.append(node('p','finance-warning','Precio bajo el mínimo: registra la autorización adicional.'));if(t.net<0)preview.append(node('p','finance-warning','Los gastos generan una pérdida neta.'));
 }
 fields.currency.addEventListener('change',()=>{privateCurrencyTouched=true;});form.elements.currency.addEventListener('change',()=>{if(!privateCurrencyTouched&&['minSalePrice','ownerTarget','fixedCommission','salePrice','costs','received'].every(k=>parseAmount(fields[k].value)===null)){fields.currency.value=fields.payoutCurrency.value=form.elements.currency.value||'BOB';choices.forEach(c=>c.sync());draw();}});section.addEventListener('input',draw);section.addEventListener('change',draw);for(const input of [form.elements.price,form.elements.currency,form.elements.status,offer]){input.addEventListener('input',draw);input.addEventListener('change',draw);}
 const report=node('section','finance-dashboard');report.id='finance-dashboard';report.innerHTML='<div class="finance-report-heading"><div><span class="eyebrow">TUS RESULTADOS, EN PRIVADO</span><h1>Ventas y comisiones</h1><p>Ganancias por venta real, cobros y efecto del cambio. Cada moneda conserva su valor.</p></div></div><h2>Resultado de las ventas</h2><div class="finance-summary"></div><h2>Dinero efectivamente cobrado</h2><div class="finance-cash-summary"></div><h2>Historial de cierres</h2><div class="finance-report-rows"></div>';sales.append(report);
 function renderReport(vehicles){nav.hidden=false;for(const b of nav.children)b.setAttribute('aria-current',b.dataset.module===(sales.hidden?'dashboard':'sales')?'page':'false');const summary=report.querySelector('.finance-summary');summary.replaceChildren();for(const group of financeSummary(vehicles)){const box=node('div','finance-currency-card');box.append(node('h3','',`${group.currency==='BOB'?'Bolivianos · Bs':'Dólares · US$'} · ${group.count} cierres`));for(const [label,key]of [['Comisión bruta','gross'],['Gastos','costs'],['Ganancia neta devengada','net'],['Cobrado equivalente en moneda de venta','received'],['Pendiente en moneda de venta','pending']]){const row=node('div');row.append(node('span','',label),node('strong',group[key]<0?'loss':'',cash(group[key],group.currency)));box.append(row);}summary.append(box);}
 const sold=vehicles.filter(v=>v.status==='sold'&&financeTotals(v.privateFinance).recorded),cashTotals={USD:0,BOB:0};let fx=0;for(const v of sold){const f=v.privateFinance,t=financeTotals(f),p=settlementTotals(f,t);cashTotals[p.currency]+=p.received;fx+=p.fxDifference;}const actualCash=report.querySelector('.finance-cash-summary');actualCash.replaceChildren(cards('Cobros en su moneda original',[['Cobrado en bolivianos',cashTotals.BOB,'BOB'],['Cobrado en dólares',cashTotals.USD,'USD'],['Diferencia cambiaria frente a lo acordado',fx,'BOB']]));
 const rows=report.querySelector('.finance-report-rows');rows.replaceChildren();if(!sold.length)rows.append(node('p','','Sin cierres con precio final registrado.'));for(const v of sold){const f=v.privateFinance,t=financeTotals(f),p=settlementTotals(f,t),row=node('article','finance-report-row'),copy=node('div');copy.append(node('strong','',v.make+' '+v.name+' · '+v.year),node('p','',`${f.saleDate||'Sin fecha'} · Venta: ${cash(t.sale,f.currency)} · Neto devengado: ${cash(t.net,f.currency)}`),node('p','',`Cobrado: ${cash(p.received,p.currency)} · Pendiente: ${cash(p.pendingBase,f.currency)}${p.foreign?' · Diferencia cambiaria: '+cash(p.fxDifference,'BOB'):''}`));const edit=node('button','','Revisar cierre');edit.type='button';edit.onclick=()=>openVehicle(v);row.append(copy,edit);rows.append(row);}
 }
 const exportButton=document.querySelector('#export-inventory');exportButton.textContent='Exportar inventario privado';exportButton.title='Incluye acuerdos privados; no compartir como catálogo público.';installHelp(form);
 return{capture,offerEnabled:()=>offer.checked,report:renderReport,setPrice(amount,currency){price.set(amount);form.elements.currency.value=currency;choices.forEach(c=>c.sync());draw();},open(vehicle){original=vehicle||null;offer.checked=!!offerParts(vehicle||{});privateCurrencyTouched=!!vehicle?.privateFinance?.currency;const f=vehicle?.privateFinance||{},currency=f.currency||moneyParts(vehicle||{}).currency||'BOB';for(const [key,input]of Object.entries(fields)){const value=f[key]??(key==='currency'||key==='payoutCurrency'?currency:key==='mode'?'percent':'');if(formats.has(key))formats.get(key).set(value);else input.value=value;}country.value='Bolivia';price.set(moneyParts(vehicle||{}).amount);choices.forEach(c=>c.sync());draw();},validate(){if(form.elements.status.value==='sold'&&parseAmount(fields.salePrice.value)!==null&&!fields.saleDate.value)fields.saleDate.value=new Date().toLocaleDateString('en-CA',{timeZone:'America/La_Paz'});return capture();}};
}
